options.getOption:
// The 15 largest groups inside the main map's viewport, in the mosaic's
// colours: the seven groups with a colour of their own keep it, and the groups
// the mosaic folds into "Other groups" are in its grey. Clicking a bar shows
// that group in the choropleth (the `grupo` variable); the group shown is in
// full colour and bold, the rest dimmed behind it.
// @constants begin
const VAR = 'grupo';
// The mosaic's ordinal palette, in the order kepler sorts `color_group`.
const COLORS = {
  American: '#62a739',
  English: '#a346c5',
  German: '#c1500e',
  Irish: '#30a0c4',
  Italian: '#ed4f8d',
  Mexican: '#5f76fc',
  'Otros grupos': '#5b5b57',
  'Puerto Rican': '#037c58',
};
const UNIT = 'people (approx.)';
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const text = theme.colors.text.primary;

const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const groups = col('grupo');
const families = col('color_group');
const people = col('personas').map((v) => (v == null ? null : Number(v)));
const picked = context.grafana.replaceVariables('${' + VAR + '}');
const shown = groups.includes(picked);

chart.off('click');
chart.on('click', (event) => {
  const id = groups[event.dataIndex];
  if (id && id !== context.grafana.replaceVariables('${' + VAR + '}')) {
    location.partial({ ['var-' + VAR]: id }, true);
  }
});

const fmt = (v) => (v == null ? '–' : v >= 1e6 ? `${(v / 1e6).toFixed(2)}M` : `${Math.round(v / 1000)}k`);

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 44, top: 8, bottom: 8, containLabel: true },
  tooltip: {
    trigger: 'item',
    formatter: (p) => {
      const i = p.dataIndex;
      const family = families[i] === 'Otros grupos' ? 'in "Other groups" on the mosaic' : 'its own colour on the mosaic';
      return `<b>${groups[i]}</b><br/>${(people[i] ?? 0).toLocaleString('en')} ${UNIT}<br/>${family}<br/><i>Click to map it in the choropleth</i>`;
    },
  },
  xAxis: { type: 'value', show: false },
  yAxis: {
    type: 'category',
    inverse: true,
    data: groups,
    axisTick: { show: false },
    axisLine: { show: false },
    axisLabel: {
      fontSize: 11,
      color: (v) => (shown && v !== picked ? muted : text),
      formatter: (v) => (v === picked ? `{picked|${v}}` : v),
      rich: { picked: { fontWeight: 'bold', fontSize: 11, color: text } },
    },
  },
  series: [
    {
      type: 'bar',
      barWidth: '72%',
      cursor: 'pointer',
      data: people.map((v, i) => ({
        value: v,
        itemStyle: {
          color: COLORS[families[i]] ?? COLORS['Otros grupos'],
          opacity: shown && groups[i] !== picked ? 0.4 : 1,
          borderColor: groups[i] === picked ? text : 'transparent',
          borderWidth: groups[i] === picked ? 1.5 : 0,
          borderRadius: [0, 3, 3, 0],
        },
      })),
      label: { show: true, position: 'right', color: muted, fontSize: 10, formatter: (p) => fmt(p.value) },
    },
  ],
};

visualEditor.code:
return {
  dataset: context.editor.dataset,
  series: context.editor.series,
  xAxis: {
    type: 'time',
  },
  yAxis: {
